  const [email, setEmail] = useState(null);

  useEffect(() => {
    const storedEmail = localStorage.getItem('userEmail');
    setEmail(storedEmail);
  }, []);

  if (email === null) {
    return <p>Loading...</p>;
  } else if (email === undefined || email === '') {
    return <Navigate to="/" />;  // Assuming "/" is your login route

