// UserProfile.js
import { useEffect, useState } from 'react';
import axios from 'axios';
//import UserProfile from './savingsm';

function UserProfile({ email }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true); 
  const [error, setError] = useState(null);

  /* useEffect(() => {
    const fetchUserData = async () => {

      try {
        const response = await axios.get(`http://localhost:8000/savings/${email}`);
        setUser(response.data);
      } catch (err) {
        console.error("API Error:", err);
        setError('Error fetching user data.');
      } finally {
        setLoading(false); // Set loading to false after the request completes, regardless of success or failure
      }
    };

    fetchUserData();
  }, [email]);


  if (loading) {  // Show loading message while fetching
      return <p>Loading user data...</p>;
  }

  if (error) {
    return <p style={{ color: 'red' }}>{error}</p>;
  }

  if (!user) { // Check for user not found *after* loading and error checks
    return <p>User not found.</p>  // More informative message
  } */


  return (
    <div className="user-profile">
      <h2>User Profile</h2>
      <p><strong>Name:</strong> {user.name}</p>
      <p><strong>Father's Name:</strong> {user.fatherName}</p>
      <p><strong>Mother's Name:</strong> {user.motherName}</p>
      <p><strong>Date of Birth:</strong> {new Date(user.dob).toLocaleDateString()}</p>
      <p><strong>Age:</strong> {user.age}</p>
      <p><strong>Gender:</strong> {user.gender}</p>
      <p><strong>Balance:</strong> ${user.balance.toFixed(2)}</p>
    </div>
  );
}

export default UserProfile;
